from pathlib import Path
p=Path('frontline.js')
s=p.read_text(encoding='utf-8')
a=s.index('function drawBriefing()')
z=s.index('function updatedCheckpoint',a)
s=s[:a]+'''function briefingBack(){const b=briefing;if(!b)return;if(b.page==='support'){b.page='weapon';drawBriefing();return;}briefing=null;if(b.continuing&&run?.state==='cleared'){screen='run';levelClear();}else campaignMenu(b.stageId);}
function drawBriefing(){const b=briefing;if(!b)return;b.page=b.page||'weapon';b.slots=b.slots||[b.loadout[0]||null,b.loadout[1]||null];b.activeSlot=b.activeSlot??0;const support=b.page==='support',base=F.WEAPONS[b.weapon],power=b.checkpoint?b.checkpoint.damage/5:1,speed=b.checkpoint?b.checkpoint.rate/2.15:1,w={...base,damage:Number((base.damage*power).toFixed(1)),rate:Number((base.rate*speed).toFixed(2))};$('#overlay').dataset.view='briefing';$('#overlay').innerHTML=`<div class="prep-shell"><header class="prep-header"><button id="briefBack" aria-label="返回">‹</button><div><h2>${support?'支援配置':'武器配置'}</h2><span>${F.STAGES[b.stageId].code} / ${F.STAGES[b.stageId].name} · ${F.DIFFICULTIES[record.difficulty].name}</span></div><b>${support?'02':'01'}<small> / 02</small></b></header><nav class="prep-steps" aria-label="整备进度"><span class="${support?'':'current'}">01 武器</span><i></i><span class="${support?'current':''}">02 支援</span></nav>${support?`<div class="prep-support-body"><div class="prep-section-title"><b>重型支援</b><span id="heavyCount">${b.loadout.length} / 2</span></div><div class="loadout-slots">${b.slots.map((id,slot)=>`<button class="loadout-slot ${id?'filled':''} ${b.activeSlot===slot?'active-slot':''}" data-slot="${slot}" ${b.checkpoint?.heavySpent?.includes(id)?'disabled':''} aria-pressed="${b.activeSlot===slot}"><small>0${slot+1}</small>${id?`${supportIcon(id)}<b>${F.ITEMS[id].name}</b><span>${b.checkpoint?.heavySpent?.includes(id)?'已使用':'点击下方更换'}</span>`:'<i>＋</i><b>添加支援</b>'}</button>`).join('')}</div><div class="prep-support-list">${F.HEAVY_ITEMS.map(id=>{const selected=b.slots.includes(id),spent=b.checkpoint?.heavySpent?.includes(id);return `<button data-pick="${id}" class="prep-support-card ${selected?'equipped':''}" ${!equipmentReady(id)||spent?'disabled':''}>${supportIcon(id)}<span><b>${F.ITEMS[id].name}</b><small>${!equipmentReady(id)?equipmentHint(id):({laser:'追踪清扫 · 持续10秒',orbitalBomb:'广域轰炸 · 5200伤害',energyShield:'能量屏障 · 持续18秒',mgTank:'自动锁敌 · 300发弹药',grenadeTank:'范围压制 · 40发榴弹'})[id]}</small></span><em>${spent?'已使用':selected?'卸下':F.ITEMS[id].arrival+'s'}<i>${selected?'−':'＋'}</i></em></button>`;}).join('')}</div></div>`:`<div class="prep-weapons"><div class="weapon-options" role="group" aria-label="选择武器">${Object.entries(F.WEAPONS).map(([id,gun])=>`<button data-weapon="${id}" class="weapon-option ${id===b.weapon?'selected':''}" ${!equipmentReady(id)?'disabled':''} aria-pressed="${id===b.weapon}">${weaponIcon(id)}<b>${gun.name}</b><small>${!equipmentReady(id)?'未解锁':id===b.weapon?'已装备':'选择'}</small></button>`).join('')}</div><div class="prep-weapon-detail">${weaponPresentation(b.weapon,w)}${!equipmentReady(b.weapon)?`<p>${equipmentHint(b.weapon)}</p>`:''}</div></div>`}<footer class="prep-footer"><span>${support?'重型支援每章各使用一次，可空置出发':'选择小队统一使用的武器'}</span><button id="${support?'deployStart':'prepNext'}" class="primary">${support?'出发':'下一步'}<b>→</b></button></footer></div>`;$('#briefBack').onclick=briefingBack;document.querySelectorAll('[data-weapon]').forEach(el=>el.onclick=()=>{b.weapon=el.dataset.weapon;mixer.ui('confirm');drawBriefing();});document.querySelectorAll('[data-slot]').forEach(el=>el.onclick=()=>{b.activeSlot=Number(el.dataset.slot);drawBriefing();});document.querySelectorAll('[data-pick]').forEach(el=>el.onclick=()=>{const id=el.dataset.pick,existing=b.slots.indexOf(id);if(existing>=0)b.slots[existing]=null;else{let slot=b.activeSlot;if(b.checkpoint?.heavySpent?.includes(b.slots[slot])){slot=1-slot;if(b.checkpoint?.heavySpent?.includes(b.slots[slot]))return;}b.slots[slot]=id;b.activeSlot=b.slots[1-slot]?slot:1-slot;}b.loadout=b.slots.filter(Boolean);mixer.ui('confirm');drawBriefing();});if(support)$('#deployStart').onclick=()=>{record.weapon=b.weapon;record.loadout=[...b.loadout];saveRecord();launch(b.level,b.weapon,b.loadout,b.continuing,b.stageId,updatedCheckpoint(b));};else{$('#prepNext').onclick=()=>{b.page='support';mixer.ui('confirm');drawBriefing();};$('#weaponAudition').onclick=()=>{mixer.unlocked=true;mixer.lastVolley=-10;mixer.weaponVolley(b.weapon,8);};}}
''' + s[z:]
s=s.replace("if(overlayState==='briefing'){campaignMenu(briefing?.stageId||0);return'handled';}","if(overlayState==='briefing'){briefingBack();return'handled';}")
p.write_text(s,encoding='utf-8')
